INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Unicast-Adresse für Gruppenkommunikation gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Nur für einzelne Geräte"}, {"text": "Ja", "correct": false, "because": "Das ist Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Adresstyp beginnt mit FF00::?', 3, '[{"text": "Multicast", "correct": true, "because": "Reserviert für Gruppen"}, {"text": "Unicast", "correct": false, "because": "Einzeladressen"}, {"text": "Anycast", "correct": false, "because": "Keine spezielle Kennung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Typen nutze ich für eine einzelne Zieladresse?', 4, '[{"text": "Unicast", "correct": true, "because": "Direkte Kommunikation"}, {"text": "Multicast", "correct": false, "because": "Für Gruppen"}, {"text": "Anycast", "correct": false, "because": "Nächster verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anycast erreicht den nächsten Server. b) Multicast geht an alle Geräte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Multicast nur an Gruppe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Adresstyps für einen Broadcast?', 5, '[{"text": "Unicast", "correct": true, "because": "Nicht für Broadcast geeignet"}, {"text": "Multicast", "correct": false, "because": "Kann Gruppen erreichen"}, {"text": "Anycast", "correct": false, "because": "Nächster Server relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Anycast mehrere Empfänger anspricht?', 2, '[{"text": "Nein", "correct": true, "because": "Nur der nächste antwortet"}, {"text": "Ja", "correct": false, "because": "Verwechselbar mit Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Typ wähle ich für eine Gruppenübertragung?', 3, '[{"text": "Multicast", "correct": true, "because": "Für mehrere Empfänger"}, {"text": "Unicast", "correct": false, "because": "Nur Einzelziel"}, {"text": "Anycast", "correct": false, "because": "Nächster Server"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften passen zu diesen Typen?', 5, '[{"text": "Unicast: Einzelkommunikation", "correct": true, "because": "Ein Ziel"}, {"text": "Multicast: Gruppenadresse", "correct": true, "because": "Mehrere Ziele"}, {"text": "Anycast: Alle Geräte", "correct": false, "because": "Nur nächstes Ziel"}, {"text": "Unicast: Broadcast", "correct": false, "because": "Falscher Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Unicast ist für direkte Verbindungen. b) Anycast nutzt Gruppenadressen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anycast ist nächster Server"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Adresse, die an eine Gruppe geht?', 4, '[{"text": "Multicast", "correct": false, "because": "Genau dafür geeignet"}, {"text": "Unicast", "correct": true, "because": "Nur Einzelziel"}, {"text": "Anycast", "correct": false, "because": "Nächster Server möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat Multicast eine feste Zieladresse?', 2, '[{"text": "Nein", "correct": true, "because": "Dynamische Gruppen"}, {"text": "Ja", "correct": false, "because": "Nicht einzeln festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Typen sind für Netzwerkdienste essenziell?', 4, '[{"text": "Unicast", "correct": true, "because": "Direkte Kommunikation"}, {"text": "Anycast", "correct": true, "because": "Nächster Server"}, {"text": "Multicast", "correct": false, "because": "Optional für Gruppen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Anycast wie Broadcast funktioniert. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Nur nächster Empfänger"}, {"text": "Ja", "correct": false, "because": "Verwechselbar, aber falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für eine Adresse an einen einzelnen Client?', 3, '[{"text": "Unicast", "correct": true, "because": "Direkte Zustellung"}, {"text": "Multicast", "correct": false, "because": "Gruppenbezogen"}, {"text": "Anycast", "correct": false, "because": "Nächster Server"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multicast beginnt mit FF00::. b) Unicast ist immer global.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unicast kann lokal sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten diese Adresstypen?', 5, '[{"text": "Anycast: Schnelle Antwort", "correct": true, "because": "Nächster Server"}, {"text": "Multicast: Effiziente Gruppen", "correct": true, "because": "Weniger Traffic"}, {"text": "Unicast: Gruppenkommunikation", "correct": false, "because": "Nur Einzelziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Adresswahl unwichtig?', 3, '[{"text": "Zieltyp", "correct": false, "because": "Entscheidet Typ"}, {"text": "Netzwerkgröße", "correct": false, "because": "Beeinflusst Einsatz"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erreicht Anycast mehrere Geräte gleichzeitig?', 2, '[{"text": "Nein", "correct": true, "because": "Nur nächstes Ziel"}, {"text": "Ja", "correct": false, "because": "Verwechselbar mit Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multicast für Video-Streaming nützlich ist?', 3, '[{"text": "Ja", "correct": true, "because": "Effizient für Gruppen"}, {"text": "Nein", "correct": false, "because": "Typisch geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Typ wähle ich für den nächsten verfügbaren Server?', 4, '[{"text": "Anycast", "correct": true, "because": "Routing zum Nächsten"}, {"text": "Unicast", "correct": false, "because": "Feste Adresse"}, {"text": "Multicast", "correct": false, "because": "Gruppenbezogen"}]');
